Value.Calculation:
Let ( [
  ~f = Char ( 9 ) ;
  ~r = Char ( 13 ) ;
  ~sql = "SELECT " & SQL.GetFieldName ( Store_OfficeAddresses::id )
       & ", " & SQL.GetFieldName ( Store_OfficeAddresses::address_name )
       & ", " & SQL.GetFieldName ( Store_OfficeAddresses::address_street )
       & ", " & SQL.GetFieldName ( Store_OfficeAddresses::address_street2 )
       & ", " & SQL.GetFieldName ( Store_OfficeAddresses::address_city )
       & ", " & SQL.GetFieldName ( Store_OfficeAddresses::address_province )
       & ", " & SQL.GetFieldName ( Store_OfficeAddresses::address_postal_zip )
       & ", " & SQL.GetFieldName ( Store_OfficeAddresses::address_country )
       & " FROM " & SQL.GetTableName ( Store_OfficeAddresses::id )
       & " WHERE " & SQL.GetFieldName ( Store_OfficeAddresses::address_type ) & " = 'office'"
       & " AND COALESCE ( " & SQL.GetFieldName ( Store_OfficeAddresses::active ) & " , 1 ) <> 0"
       & " ORDER BY " & SQL.GetFieldName ( Store_OfficeAddresses::address_name ) & " ASC" ;
  ~rows = ExecuteSQL ( ~sql ; ~f ; ~r ) ;
  ~rows = If ( ~rows = "?" ; "" ; ~rows ) ;
  ~count = ValueCount ( ~rows )
] ;
  While (
    [ ~i = 0 ; ~json = "[]" ] ;
    ~i < ~count ;
    [
      ~row = Substitute ( GetValue ( ~rows ; ~i + 1 ) ; ~f ; ~r ) ;
      ~json = JSONSetElement ( ~json ; ~i ;
        JSONSetElement ( "{}" ;
          [ "id" ; GetValue ( ~row ; 1 ) ; JSONString ] ;
          [ "addressName" ; GetValue ( ~row ; 2 ) ; JSONString ] ;
          [ "addressStreet" ; GetValue ( ~row ; 3 ) ; JSONString ] ;
          [ "addressStreet2" ; GetValue ( ~row ; 4 ) ; JSONString ] ;
          [ "addressCity" ; GetValue ( ~row ; 5 ) ; JSONString ] ;
          [ "addressProvince" ; GetValue ( ~row ; 6 ) ; JSONString ] ;
          [ "addressPostalZip" ; GetValue ( ~row ; 7 ) ; JSONString ] ;
          [ "addressCountry" ; Let ( ~c = GetValue ( ~row ; 8 ) ; If ( ~c = "CA" ; "Canada" ; ~c ) ) ; JSONString ]
        ) ; JSONObject ) ;
      ~i = ~i + 1
    ] ;
    ~json
  )
)
